+const { lastSpaceBefore } = require('./words');
+
+const ELLIPSIS = '\u2026';
+
+function excerpt(text, limit) {
+  const trimmed = text.trim();
+  const cut = lastSpaceBefore(trimmed, limit);
+  return trimmed.slice(0, cut).trimEnd() + ELLIPSIS;
+}
